  ["="] = {{x=1,y=5},{x=2,y=5},{x=3,y=5},{x=4,y=5},{x=5,y=5},{x=1,y=3},{x=2,y=3},{x=3,y=3},{x=4,y=3},{x=5,y=3}},
}
local Text = {}
Text.__index = Text

function Text.new(str, pos, scale)
    local self = setmetatable({})
    self.String = str
    self.Scale = scale or 5
    self.Position = pos or {x=0,y=0}
    return self
end

function Text:draw()
    local cursor = 0
    for char in self.String:gmatch(".") do
        if not letters[char] then char = '?' end
        for pos in letters[char] do
            _G.Shape.DrawSquare((( cursor * 14 * self.Scale ) + (pos.x * 2 * self.Scale)) + self.Position.x, (pos.y * 2 * self.Scale) + self.Position.y, self.Scale * 2)
        end
        

    end
end

return Text